# Generate candidate: each 2x2 object receives four diagonal rays, with the observed corner-color rotation.
out=[row[:] for row in grid]
blocks=[(1,3),(5,1)]
for r,c in blocks:
 src={'tl':grid[r-1][c-1],'tr':grid[r-1][c+2],'br':grid[r+2][c+2] if r+2<len(grid) and c+2<len(grid[0]) else 0,'bl':grid[r+2][c-1] if r+2<len(grid) and c-1>=0 else 0}
 # outgoing rays sourced into TL<-BL, TR<-TL, BR<-TR, BL<-BR
 rays=[(r-1,c-1,-1,-1,src['bl']),(r-1,c+2,-1,1,src['tl']),(r+2,c+2,1,1,src['tr']),(r+2,c-1,1,-1,src['br'])]
 for i,j,di,dj,v in rays:
  while 0<=i<len(grid) and 0<=j<len(grid[0]):
   if v: out[i][j]=v
   i+=di;j+=dj
print(out)
